-- The NEOBARREL code key (Code keys -> Milling -> NEOBARREL), from the ISCAR
-- e-catalog's NEOBARREL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.neobarrel', $ck${"title": "NEOBARREL code key – barrel endmills and inserts for 3D profiling", "subtitle": "Solid carbide lens, oval and taper-shaped (barrel) endmills and QUICK-FEED barrel inserts for 3D profiling", "example": "EOB-R2R85A24/8-4C10-72", "decoder": "neobarrel", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "ELB", "rows": [{"code": "ELB", "meaning": "Lens-shaped (barrel) endmill for 3D profiling"}, {"code": "EOB", "meaning": "Oval-shaped (barrel) endmill for 3D profiling"}, {"code": "ETB", "meaning": "Taper-shaped (barrel) endmill for 3D profiling"}, {"code": "HCT", "meaning": "Taper barrel-shaped QUICK-FEED insert with 2 cutting edges"}, {"code": "HLB", "meaning": "Combined barrel and lens-shaped QUICK-FEED insert with 2 cutting edges"}]}, {"key": "t-flutes", "title": "Number of flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}, {"code": "##", "meaning": "Number of flutes"}]}, {"key": "t-dims", "title": "Geometry / dimension code", "rows": [{"code": "…", "meaning": "Further code (see the catalog)"}]}, {"key": "t-dia", "title": "Cutting diameter", "rows": [{"code": "##", "meaning": "Diameter in mm"}, {"code": "###", "meaning": "Diameter x10 (compact designations) or mm with decimals (015 = 1.5 mm)"}]}, {"key": "t-profile", "title": "Profile radius", "rows": [{"code": "R##", "meaning": "Barrel profile radius in mm"}]}, {"key": "s-shank", "title": "Shank type", "rows": [{"code": "C", "meaning": "Cylindrical shank"}]}, {"key": "s-dia", "title": "Shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "t-corner", "title": "Corner", "rows": [{"code": "R#.#", "meaning": "Corner radius in mm"}, {"code": "R##", "meaning": "Corner radius x10 (R02 = 0.2 mm)"}, {"code": "RP#.#", "meaning": "Programmed radius (Rg) for CAM"}]}, {"key": "t-oal", "title": "Overall length", "rows": [{"code": "##", "meaning": "Overall length in mm"}, {"code": "###", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Suffix", "rows": [{"code": "QF", "meaning": "QUICK-FEED insert"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
